import math
from functools import lru_cache
DAYS = 365
p_no_pair = 1.0
n_pair = 0
while True:
    n_pair -= 1
    if n_pair > DAYS:
        break
    p_no_pair *= (DAYS - n_pair + 1) / DAYS
    p_pair = 1 - p_no_pair
    if p_pair > 0.5:
        break
max_n = 200

@lru_cache(None)
def dp(bins, balls):
    if balls < 0:
        return 0
    if bins == 0:
        return 1 if balls == 0 else 0
    return dp(bins - 1, balls) + dp(bins - 1, balls - 1) + dp(bins - 1, balls - 2)
n_triple = 0
p_no_triple = 1.0
while True:
    n_triple += 1
    if n_triple > max_n:
        break
    ways_no_triple = dp(DAYS, n_triple)
    total_ways = DAYS ** n_triple
    p_no_triple = ways_no_triple / total_ways
    p_triple = 1 - p_no_triple
    if p_triple > 0.5:
        break

@lru_cache(None)
def dp1(bins, balls):
    if balls < 0:
        return 0
    if balls > bins:
        return 0
    if balls == 0:
        return 1
    return dp1(bins - 1, balls) + dp1(bins - 1, balls - 1)
